"""The inner loop of phase 1: every check the phase gate runs, in one command, with a platform dry run.
    python3 tools/check_workflow.py [workflow.json]
Prints each problem with its format-rule id (see .claude/skills/compose-workflow/format-rules.md). Fix, run again, repeat until it
prints READY; then publish. The phase gate runs the same checks, so a workflow that says READY passes it.
"""
import json, pathlib, sys
HERE = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(HERE)); sys.path.insert(0, str(HERE.parent))
import check_design, inputs, lint
def check(path="workflow.json"):
    """(must-fix problems, warnings)."""
    wf = json.load(open(path))
    base = inputs.base_url()
    bad, warn, _ = lint.lint(wf, base)
    bad = list(bad)
    if not pathlib.Path("design.json").exists():
        bad.append("[design] design.json is not written yet")
    else:
        bad += ["[design] " + p for p in check_design.check(pathlib.Path("."))]
    try:
        import freya
        res = freya.validate_workflow("dry", wf)
        if isinstance(res, dict) and res.get("valid") is False:
            bad.append("[platform] the dry run rejects the workflow: " + json.dumps(res)[:600])
    except Exception as e:
        warn.append("[platform] the dry run could not run (%s); publish.py runs it again" % str(e)[:160])
    return bad, warn
if __name__ == "__main__":
    bad, warn = check(sys.argv[1] if len(sys.argv) > 1 else "workflow.json")
    for w in warn:
        print("WARN", w)
    for b in bad:
        print("FAIL", b)
    if bad:
        print("NOT READY: %d must-fix. Fix them, then run this again." % len(bad))
    else:
        print("READY: no must-fix problems (%d warnings). Publish with python3 tools/publish.py workflow.json" % len(warn))
    sys.exit(1 if bad else 0)
"""Check design.json against rules.json and workflow.json: every live rule has a mechanism that exists in the workflow, hard rules are never prompt-only,
mandated wording is in the workflow, no node carries too many prompt-only rules, the workflow stays small.
    python3 tools/check_design.py        (run it before you finish phase 1: the same check gates the phase)
"""
import json, pathlib, re, sys
LIVE = ("decided", "proposed", "unresolved")
HARD = ("gate", "calc", "state")
COUNTED = re.compile(r"\d|\b(once|twice|thrice|times|attempts?)\b", re.I)
DENSITY = 8        # most prompt-only rules the model is shown in one node
SIZE = 1000        # most lines of workflow.json (indent 2)
def check(work):
    """Problems with design.json. Hard rules (gate, calc, state, or any rule that names a number or a count) must be structure or code."""
    try:
        design = json.load(open(work / "design.json"))
        rules = json.load(open(work / "rules.json"))["rules"]
        wf = json.load(open(work / "workflow.json"))
    except Exception as e:
        return ["design.json, rules.json or workflow.json cannot be read: %s" % e]
    names = set(wf["nodes"])
    for n in wf["nodes"].values():
        for t in n.get("tools", []) + n.get("pre_actions", []):
            names.add(t.get("function", {}).get("name", ""))
    for t in wf.get("tools", []):
        names.add(t.get("function", {}).get("name", ""))
    names.discard("")
    row_of, bad = {}, []
    for row in design.get("rows", []):
        if row.get("mechanism") not in ("structure", "code", "prompt"):
            bad.append("design row %s: mechanism must be structure, code or prompt" % row.get("rules") or row.get("rule"))
        if row.get("mechanism") != "prompt" and not any(nm in str(row.get("where", "")) for nm in names):
            bad.append("design row %s: `where` names no node or tool of workflow.json" % (row.get("rules") or row.get("rule")))
        for rid in row.get("rules", []) + ([row["rule"]] if row.get("rule") else []):
            row_of[rid] = row
    shown = {}                                       # node -> live rules that only the prompt of that node carries
    text = _norm(" ".join(_strings(wf)))
    for r in rules:
        if r.get("status") not in LIVE:
            continue
        row = row_of.get(r["id"])
        if row is None:
            bad.append("rule %s has no row in design.json" % r["id"])
            continue
        if row["mechanism"] == "prompt" and (r.get("class") in HARD or r.get("kind") in ("gate", "limit", "allowed_set") or COUNTED.search(r.get("quote", ""))):
            bad.append("rule %s (%s) is prompt-only but is a hard rule: limits, windows, amounts and every counter must be structure or code" % (r["id"], r.get("class")))
        if row["mechanism"] == "prompt":
            nodes = [n for n in wf["nodes"] if n in str(row.get("where", ""))]
            if not nodes and "system prompt" not in str(row.get("where", "")).lower().replace("_", " "):
                bad.append("rule %s is carried by a prompt but `where` names neither a node of workflow.json nor system_prompt" % r["id"])
            for n in nodes:
                shown.setdefault(n, []).append(r["id"])
        if r.get("kind") == "wording" and _norm(r.get("wording", "")) not in text:
            bad.append("rule %s mandates exact wording, which is not in workflow.json: %r" % (r["id"], str(r.get("wording"))[:80]))
    for n, ids in shown.items():
        if len(ids) > DENSITY:
            bad.append("node %s shows the model %d rules (%s); at most %d: split the node by state, or settle the interplay in code and show conclusions" % (n, len(ids), ", ".join(ids), DENSITY))
    lines = len(json.dumps(wf, indent=2).splitlines())
    if lines > SIZE:
        bad.append("workflow.json is %d lines (indent 2); the limit is %d. Remove nodes or prompt text that no rule needs" % (lines, SIZE))
    return bad
def _norm(s):
    return re.sub(r"\s+", " ", str(s)).strip().lower()
def _strings(x):
    if isinstance(x, str):
        yield x
    elif isinstance(x, dict):
        for v in x.values():
            yield from _strings(v)
    elif isinstance(x, list):
        for v in x:
            yield from _strings(v)
if __name__ == "__main__":
    problems = check(pathlib.Path("."))
    for p in problems:
        print("FAIL", p)
    print("check_design:", "FAILED" if problems else "ok")
    sys.exit(1 if problems else 0)
"""Lint, save (create or update in place), publish and read back a workflow. Brief-independent.
    python3 tools/publish.py workflow.json            prints {"workflow_id", "agent_id"}
Uses freya.save_workflow with the slot from $BUILDER_SLOT and the state file $BUILDER_SLOT_STATE, so repeated calls
update the same workflow instead of filling the workspace. Refuses to publish a workflow that fails lint.
"""
import json, os, pathlib, sys
HERE = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(HERE)); sys.path.insert(0, str(HERE.parent))
import freya, lint, inputs
wf = json.load(open(sys.argv[1]))
base = inputs.base_url()
bad, warn, lines = lint.lint(wf, base)
for w in warn:
    print("WARN", w)
if bad:
    print("\n".join("FAIL " + b for b in bad))
    sys.exit("not published: lint failed")
print("dry run:", freya.validate_workflow("dry", wf))
slot, state = os.environ.get("BUILDER_SLOT", "dev"), os.environ.get("BUILDER_SLOT_STATE", str(HERE.parent / ".slots.json"))
r = freya.save_workflow(slot, wf, state_file=state)
got = freya.api("GET", "/api/v2/workflow/" + r["workflow_id"], workspaceId=freya.workspace_id())["workflow"]["workflow"]
for name, n in wf["nodes"].items():
    g = got["nodes"].get(name)
    if g is None:
        print("READBACK missing node", name); continue
    for key in ("tools", "pre_actions", "transitions", "response_mapping", "extraction_schema"):
        if len(n.get(key, [])) != len(g.get(key, [])):
            print("READBACK %s.%s: sent %d, stored %d (the platform dropped something)" % (name, key, len(n.get(key, [])), len(g.get(key, []))))
log = json.load(open(HERE.parent / "published.json")) if (HERE.parent / "published.json").exists() else []
(HERE.parent / "versions").mkdir(exist_ok=True)
fname = "versions/pub-%d.json" % (len(log) + 1)
json.dump(wf, open(HERE.parent / fname, "w"))
log.append({"seq": len(log) + 1, "file": fname})
json.dump(log, open(HERE.parent / "published.json", "w"))
print(json.dumps({"workflow_id": r["workflow_id"], "agent_id": r["agent_id"], "lines": lines}))
